 SELECT jsonb_object_agg(v.id::text,md5(public.pdc_qc_operation_lines_379(v.id)::text)) INTO before_values FROM public.vehicles v;
 FOR pair IN SELECT value FROM jsonb_array_elements($guards$[["d ~ '\\m(BONNET[ -]*PROTECT(OR|ER)S?|WEATHER[ -]*(SHIELD|SHEILD)S?)\\M'","(CASE WHEN strpos(d,'BONNET')>0 OR strpos(d,'WEATHER')>0 THEN d ~ '\\m(BONNET[ -]*PROTECT(OR|ER)S?|WEATHER[ -]*(SHIELD|SHEILD)S?)\\M' ELSE false END)"],["d ~ '\\m(ADDITIONAL|SECOND|2ND|EXTRA)\\M.*(\\mRIMS?\\M|SPARES?.*\\m(WHEELS?|TYRES?|TIRES?)\\M|\\mSPARES?[ ]*$)'","(CASE WHEN strpos(d,'ADDITIONAL')>0 OR strpos(d,'SECOND')>0 OR strpos(d,'2ND')>0 OR strpos(d,'EXTRA')>0 THEN d ~ '\\m(ADDITIONAL|SECOND|2ND|EXTRA)\\M.*(\\mRIMS?\\M|SPARES?.*\\m(WHEELS?|TYRES?|TIRES?)\\M|\\mSPARES?[ ]*$)' ELSE false END)"],["d ~ '\\ySUBLET\\y|^SUB\\y|^TRANSPORT\\y|\\ySUPPLIER[ -]*(?:FITTED|TO FIT|TO SUPPLY[[:space:]]*(?:AND|&)[[:space:]]*FIT)\\y|\\y(?:FITTED|FIT) BY (?:EXTERNAL )?SUPPLIER\\y'","(CASE WHEN strpos(d,'SUB')>0 OR strpos(d,'TRANSPORT')>0 OR strpos(d,'SUPPLIER')>0 THEN d ~ '\\ySUBLET\\y|^SUB\\y|^TRANSPORT\\y|\\ySUPPLIER[ -]*(?:FITTED|TO FIT|TO SUPPLY[[:space:]]*(?:AND|&)[[:space:]]*FIT)\\y|\\y(?:FITTED|FIT) BY (?:EXTERNAL )?SUPPLIER\\y' ELSE false END)"],["d ~ 'MMT.*SEAT[ -]?COVERS?'","(CASE WHEN strpos(d,'MMT')>0 THEN d ~ 'MMT.*SEAT[ -]?COVERS?' ELSE false END)"],["d ~ '\\yWHIP[ -]?FLAGS?\\y|\\yANDERSONS?\\y|\\y175[[:space:]]*(?:A|AMP|AMPS)?\\y.*JUMP[ -]?START|JUMP[ -]?START.*\\y175\\y|\\yBATTERY[ -]*(?:BOX(?:ES)?|ISOLATORS?)\\y|\\yDUAL[ -]?BATTERY\\y|\\y(?:UHF|GME)\\y|\\y(?:DRIVING|ROOF[ -]?RACK)[ -]*LIGHTS?\\y|\\yARB\\y.*\\y(?:SOLIS|INTENSITY)\\y'","(CASE WHEN strpos(d,'WHIP')>0 OR strpos(d,'ANDERSON')>0 OR strpos(d,'175')>0 OR strpos(d,'JUMP')>0 OR strpos(d,'BATTERY')>0 OR strpos(d,'DUAL')>0 OR strpos(d,'UHF')>0 OR strpos(d,'GME')>0 OR strpos(d,'DRIVING')>0 OR strpos(d,'ROOF')>0 OR strpos(d,'ARB')>0 THEN d ~ '\\yWHIP[ -]?FLAGS?\\y|\\yANDERSONS?\\y|\\y175[[:space:]]*(?:A|AMP|AMPS)?\\y.*JUMP[ -]?START|JUMP[ -]?START.*\\y175\\y|\\yBATTERY[ -]*(?:BOX(?:ES)?|ISOLATORS?)\\y|\\yDUAL[ -]?BATTERY\\y|\\y(?:UHF|GME)\\y|\\y(?:DRIVING|ROOF[ -]?RACK)[ -]*LIGHTS?\\y|\\yARB\\y.*\\y(?:SOLIS|INTENSITY)\\y' ELSE false END)"],["d ~ '\\y(?:TYRES?|TIRES?|BFG|BF[ -]?GOODRICH)\\y'","(CASE WHEN strpos(d,'TYRE')>0 OR strpos(d,'TIRE')>0 OR strpos(d,'BFG')>0 OR strpos(d,'BF')>0 THEN d ~ '\\y(?:TYRES?|TIRES?|BFG|BF[ -]?GOODRICH)\\y' ELSE false END)"],["d ~ '\\ySEAT[ -]?COVERS?\\y'","(CASE WHEN strpos(d,'SEAT')>0 THEN d ~ '\\ySEAT[ -]?COVERS?\\y' ELSE false END)"],["d ~ '\\yFIRE[ -]*(?:EXTINGUISHERS?|EXT)\\y|\\yWATER[ -]?PROTECTORS?\\y|\\yCARGO[ -]?BARRIERS?\\y|\\yRECOVERY[ -]?POINTS?\\y'","(CASE WHEN strpos(d,'FIRE')>0 OR strpos(d,'WATER')>0 OR strpos(d,'CARGO')>0 OR strpos(d,'RECOVERY')>0 THEN d ~ '\\yFIRE[ -]*(?:EXTINGUISHERS?|EXT)\\y|\\yWATER[ -]?PROTECTORS?\\y|\\yCARGO[ -]?BARRIERS?\\y|\\yRECOVERY[ -]?POINTS?\\y' ELSE false END)"],["d ~ '\\y(?:WINDOW[ -]?TINTS?|(?:DARKNESS|DARKEST)[ -]?LEGAL.*TINT)\\y'","(CASE WHEN strpos(d,'WINDOW')>0 OR strpos(d,'DARKNESS')>0 OR strpos(d,'DARKEST')>0 THEN d ~ '\\y(?:WINDOW[ -]?TINTS?|(?:DARKNESS|DARKEST)[ -]?LEGAL.*TINT)\\y' ELSE false END)"],["d ~ '\\yLONG[ -]?RANG(?:E|ER)\\y.*\\yTANKS?\\y'","(CASE WHEN strpos(d,'LONG')>0 THEN d ~ '\\yLONG[ -]?RANG(?:E|ER)\\y.*\\yTANKS?\\y' ELSE false END)"],["d ~ '\\yARB\\y.*\\yFRONTIER\\y.*\\yTANKS?\\y'","(CASE WHEN strpos(d,'ARB')>0 THEN d ~ '\\yARB\\y.*\\yFRONTIER\\y.*\\yTANKS?\\y' ELSE false END)"],["d ~ '\\m(FILL[ ]+(WITH[ ]+)?FUEL|FULL[ ]+TANK[ ]+(OF[ ]+)?FUEL|REFUEL(LING|ING)?|PIT[ ]*(AND|&)[ ]*WEIGH)\\M'","(CASE WHEN strpos(d,'FUEL')>0 OR strpos(d,'WEIGH')>0 THEN d ~ '\\m(FILL[ ]+(WITH[ ]+)?FUEL|FULL[ ]+TANK[ ]+(OF[ ]+)?FUEL|REFUEL(LING|ING)?|PIT[ ]*(AND|&)[ ]*WEIGH)\\M' ELSE false END)"],["d ~ 'BATTERY[ ]*100[ ]*%'","(CASE WHEN strpos(d,'BATTERY')>0 THEN d ~ 'BATTERY[ ]*100[ ]*%' ELSE false END)"],["d ~ '\\m(HEAD[ -]?(LIGHT|LAMP)S?[ -]*(AUTO[ -]*)?ON|SPOT[ -]?LIGHTS?)\\M'","(CASE WHEN strpos(d,'HEAD')>0 OR strpos(d,'SPOT')>0 THEN d ~ '\\m(HEAD[ -]?(LIGHT|LAMP)S?[ -]*(AUTO[ -]*)?ON|SPOT[ -]?LIGHTS?)\\M' ELSE false END)"],["d ~ '\\mMINE[ -]?BARS?