os(d,'RYCO')>0 THEN d ~ 'RYCO.*CATCH[ -]?CAN.*KIT' ELSE false END)"],["d ~ 'ADDITIONAL.*(GENUINE|ALLOY).*RIM'","(CASE WHEN strpos(d,'ADDITIONAL')>0 THEN d ~ 'ADDITIONAL.*(GENUINE|ALLOY).*RIM' ELSE false END)"],["d ~ 'SPARE[ -]?(TYRE|WHEEL).*(HOLDER|MOUNT).*PMB.*CAB[ -]?RACK'","(CASE WHEN strpos(d,'SPARE')>0 THEN d ~ 'SPARE[ -]?(TYRE|WHEEL).*(HOLDER|MOUNT).*PMB.*CAB[ -]?RACK' ELSE false END)"],["d ~ 'CERTIFIED.*MESH.*CAB[ -]?RACK.*BARRIER'","(CASE WHEN strpos(d,'CERTIFIED')>0 THEN d ~ 'CERTIFIED.*MESH.*CAB[ -]?RACK.*BARRIER' ELSE false END)"],["d ~ 'ADDITIONAL.*ALLOY.*RIMS?'","(CASE WHEN strpos(d,'ADDITIONAL')>0 THEN d ~ 'ADDITIONAL.*ALLOY.*RIMS?' ELSE false END)"],["d ~ '\\m(800[ ]*MM[ ]*)?TOOL[ -]?BOX(ES)?\\M'","(CASE WHEN strpos(d,'TOOL')>0 THEN d ~ '\\m(800[ ]*MM[ ]*)?TOOL[ -]?BOX(ES)?\\M' ELSE false END)"],["d ~ 'TIE[ -]?DOWN.*(POINT|ANCHOR).*FLOOR'","(CASE WHEN strpos(d,'TIE')>0 THEN d ~ 'TIE[ -]?DOWN.*(POINT|ANCHOR).*FLOOR' ELSE false END)"],["d ~ 'SPARE[ -]?WHEEL.*(MOUNT|HOLDER).*\\m(TRAY|TOOL[ -]?BOX)'","(CASE WHEN strpos(d,'SPARE')>0 THEN d ~ 'SPARE[ -]?WHEEL.*(MOUNT|HOLDER).*\\m(TRAY|TOOL[ -]?BOX)' ELSE false END)"],["d ~ 'BUSHRANGER.*COVERT.*WINCH|ROOF[ -]?RACK|RHINO[ -]?RACK|FIRST[ -]?AID.*KIT'","(CASE WHEN strpos(d,'BUSHRANGER')>0 OR strpos(d,'ROOF')>0 OR strpos(d,'RHINO')>0 OR strpos(d,'FIRST')>0 THEN d ~ 'BUSHRANGER.*COVERT.*WINCH|ROOF[ -]?RACK|RHINO[ -]?RACK|FIRST[ -]?AID.*KIT' ELSE false END)"],["d ~ 'ANTI[ -]?THEFT.*(NUMBER|NO[ .-]?)[ -]?PLATE.*SCREW'","(CASE WHEN strpos(d,'ANTI')>0 THEN d ~ 'ANTI[ -]?THEFT.*(NUMBER|NO[ .-]?)[ -]?PLATE.*SCREW' ELSE false END)"],["d ~ '\\mEV[ -]?TAGS?\\M'","(CASE WHEN strpos(d,'EV')>0 THEN d ~ '\\mEV[ -]?TAGS?\\M' ELSE false END)"],["d ~ '\\mPMB[ -]*0*02\\M|\\mPMB[ -]+ITEMS?\\M|^PMB([A-Z]?[0-9]+)?\\M'","(CASE WHEN strpos(d,'PMB')>0 THEN d ~ '\\mPMB[ -]*0*02\\M|\\mPMB[ -]+ITEMS?\\M|^PMB([A-Z]?[0-9]+)?\\M' ELSE false END)"],["d ~ '\\yARB\\y'","(CASE WHEN strpos(d,'ARB')>0 THEN d ~ '\\yARB\\y' ELSE false END)"],["d ~ 'ARB.*COMMERCIAL.*BULL[ -]?BAR'","(CASE WHEN strpos(d,'ARB')>0 THEN d ~ 'ARB.*COMMERCIAL.*BULL[ -]?BAR' ELSE false END)"],["d ~ 'HILUX'","(CASE WHEN strpos(d,'HILUX')>0 THEN d ~ 'HILUX' ELSE false END)"],["d ~ 'MY[ ]?26'","(CASE WHEN strpos(d,'MY')>0 THEN d ~ 'MY[ ]?26' ELSE false END)"],["d ~ 'TIE[ -]?DOWN.*POINT.*FLOOR'","(CASE WHEN strpos(d,'TIE')>0 THEN d ~ 'TIE[ -]?DOWN.*POINT.*FLOOR' ELSE false END)"],["d ~ 'PMB.*STEEL.*TRAY|PMB.*TRAY.*STEEL'","(CASE WHEN strpos(d,'PMB')>0 THEN d ~ 'PMB.*STEEL.*TRAY|PMB.*TRAY.*STEEL' ELSE false END)"],["d ~ 'MESH.*CAB[ -]?RACK.*BARRIER'","(CASE WHEN strpos(d,'MESH')>0 THEN d ~ 'MESH.*CAB[ -]?RACK.*BARRIER' ELSE false END)"]]$guards$::jsonb) LOOP
  IF strpos(d,pair->>0)=0 THEN RAISE EXCEPTION 'expected_regex_missing'; END IF;
  d:=replace(d,pair->>0,pair->>1);
 END LOOP;
 EXECUTE d;
 SELECT jsonb_object_agg(v.id::text,md5(public.pdc_qc_operation_lines_379(v.id)::text)) INTO after_values FROM public.vehicles v;
 IF before_values IS DISTINCT FROM after_values THEN RAISE EXCEPTION 'canonical_operation_parity_failed'; END IF;
END $repair$;
